export const GLOSSARY_SHARD = Object.freeze({"bitcoin-halving":{"slug":"bitcoin-halving","cat":"basics","en":"Bitcoin halving","contentLocale":"ja","term":"ビットコイン半減期","aka":["半減期","Halving","ハービング"],"short":"ビットコイン半減期とは、21万ブロックごと（約4年ごと）に、マイナーが受け取る新規発行のブロック報酬が半分になるイベントのことです。","body":[[["ビットコイン","bitcoin"],"の新規発行は、マイナーへのブロック報酬としてのみ行われます。2009年の開始時は1ブロック50 BTCでしたが、半減期ごとに25、12.5、6.25と減り、2024年4月の半減期で3.125 BTCになりました。この仕組みによって、総発行量が2100万枚を超えないようになっています。"],"半減期は日付ではなくブロック数で決まるため、正確な日時は予測値として示されるだけです。ブロックは平均約10分ごとに生成されるので、21万ブロックはおよそ4年に相当します。",["半減期の後は新規供給が減る一方で、マイナーの収入も減ります。採算の合わないマイナーが撤退すれば、",["ハッシュレート","hash-rate"],"が一時的に下がることもあります。過去の半減期後の値動きがよく話題になりますが、過去の傾向が今後も繰り返されるとは限りません。"]],"example":"例えば、ブロック報酬が3.125 BTCで、1日あたり約144ブロック（24時間 × 1時間6ブロック）が生成されるとすると、1日の新規発行量は3.125 × 144 = 450 BTCです。次の半減期で報酬が1.5625 BTCになれば、1日の新規発行量は約225 BTCに減ります。マイナーにとっては、価格が変わらなければ報酬収入が半分になる計算です。","mistakes":["半減期を特定の日付に起こるイベントだと思い込むこと。","「半減期の後は必ず価格が上がる」と過去のパターンをそのまま当てはめること。","半減期で自分が保有するビットコインの量まで半分になると誤解すること。"],"faq":[{"q":"次のビットコイン半減期はいつですか？","a":"2024年4月の次は、ブロック数で数えて約4年後の2028年頃と見込まれています。正確な時期はブロックの生成ペースによって前後します。"},{"q":"半減期は何回続きますか？","a":"ブロック報酬が1サトシ未満になるまで続き、新規発行は2140年頃に終わると見積もられています。"}],"title":"ビットコイン半減期とは？仕組みとブロック報酬の推移","description":"ビットコイン半減期の意味、ブロック報酬の推移、新規発行量やマイナーへの影響を具体的な計算で解説します。","related":[["bitcoin","ビットコイン（BTC）","ビットコイン（BTC）とは、2009年に運用が始まった最初の暗号資産で、発行上限2100万枚、管理者のいないネットワークでプルーフ・オブ・ワークにより運営されています。"],["mining","マイニング（採掘）","マイニング（採掘）とは、プルーフ・オブ・ワークのブロックチェーンで計算処理を行って取引をブロックにまとめ、その報酬として新規発行の暗号資産と手数料を受け取る活動です。"],["proof-of-work","プルーフ・オブ・ワーク（PoW）","プルーフ・オブ・ワーク（PoW）とは、マイナーが大量の計算で競争し、最初に条件を満たす答えを見つけた者が新しいブロックを追加できるコンセンサスの仕組みです。"],["hash-rate","ハッシュレート","ハッシュレートとは、プルーフ・オブ・ワーク（PoW）のブロックチェーンでマイニング機器が1秒間に計算できるハッシュの回数のことで、ネットワーク全体の計算力を表します。"],["satoshi","サトシ（sats）","サトシ（sats）とは、ビットコインの最小単位で、1サトシは1億分の1 BTC（0.00000001 BTC）に相当します。"]],"lesson":null,"coin":{"slug":"bitcoin","name":"Bitcoin","symbol":"BTC"},"tool":null,"cta":false},"stop-loss":{"slug":"stop-loss","cat":"trading","en":"Stop-loss order","contentLocale":"ja","term":"損切り注文（ストップロス）","aka":["ストップロス","損切り","逆指値","Stop loss"],"short":"損切り注文（ストップロス）とは、価格があらかじめ決めた水準に達したときに自動で決済し、損失がそれ以上広がらないようにする注文です。","body":[["日本の取引所では、損切りに「逆指値注文」を使うのが一般的です。",["買いポジション","long-and-short"],"なら現在価格より下に、売り（ショート）ポジションなら上にトリガー価格を設定します。価格がトリガーに達すると、成行または指値の注文が自動で発注されます。"],"損切りの最大の目的は、感情に左右されずに損失を限定することです。損切り価格は「ここまで来たら自分の見立てが外れた」と言える水準に置き、そこから逆算してポジションの大きさを決めます。",["注意点として、成行型の損切りは急変時に設定価格より不利な価格で約定することがあります。逆に指値型は、価格が一気に飛ぶと約定しないまま損失が拡大するおそれがあります。",["先物取引","futures-contract"],"では、損切り価格を",["強制ロスカット","liquidation"],"価格より手前に置いておくことが重要です。"]],"example":"例えば、総資金100万円で、1回の損失を2%（2万円）までにすると決めたとします。BTCを1,000万円で買い、950万円に損切りを置くなら、値幅は5%です。2万円 ÷ 5% = 40万円がポジションの目安なので、0.04 BTCを買います。価格が950万円に達して損切りされれば、損失は約2万円に収まります。","mistakes":["含み損が出てから、損切り価格を何度も不利な方向にずらすこと。","値動きの幅を考えずに損切りを近すぎる位置に置き、普段の揺れで何度も損切りされること。","レバレッジ取引で、損切り価格が強制ロスカット価格より遠くにあることに気づかないこと。"],"faq":[{"q":"損切りはどこに置くのがよいですか？","a":"決まった正解はありませんが、自分の取引の前提が崩れる価格に置き、その値幅から許容損失に合うポジションサイズを決めるのが基本です。"},{"q":"損切り注文は必ず設定した価格で約定しますか？","a":"成行型の場合、急変時には設定価格より不利な価格で約定することがあります。指値型は、価格が飛ぶと約定しない可能性があります。"}],"title":"損切り注文（ストップロス）とは？設定方法と注意点","description":"損切り注文（ストップロス）の仕組み、逆指値との関係、損切り価格とポジションサイズの決め方を具体例で解説します。","related":[["take-profit","利益確定注文（テイクプロフィット）","利益確定注文（テイクプロフィット）とは、価格が目標の水準に達したときに自動で決済し、含み益を実際の利益として確定させる注文です。"],["stop-limit-order","ストップリミット注文","ストップリミット注文とは、価格がトリガー価格（ストップ価格）に達したときに、あらかじめ指定した価格で指値注文を自動発注する注文方法です。"],["trailing-stop","トレーリングストップ","トレーリングストップとは、価格が有利な方向に動くと損切り価格も自動で追いかけて移動し、反転して一定幅戻ったときに決済する注文です。"],["position-sizing","ポジションサイジング（建玉管理）","ポジションサイジングとは、1回の取引でどれだけの数量を建てるかを、許容できる損失額と損切りまでの距離から逆算して決める資金管理の方法です。"],["liquidation","強制ロスカット（清算）","強制ロスカット（清算）とは、レバレッジ取引で損失が膨らみ、証拠金が維持証拠金を下回ったときに、取引所がポジションを強制的に決済する仕組みです。"]],"lesson":{"id":"E17","slug":"stop-loss-is-a-plan","ep":17,"title":"利確と損切りは計画であって、保険ではない"},"coin":null,"tool":"/liquidations","cta":false},"unrealized-pnl":{"slug":"unrealized-pnl","cat":"derivatives","en":"Unrealized PnL","contentLocale":"ja","term":"含み損益（未実現損益）","aka":["未実現損益","含み益","含み損","unrealized PnL"],"short":"含み損益（未実現損益）とは、まだ決済していないポジションについて、現在の価格で決済したと仮定した場合の利益または損失のことです。","body":["ポジションを持っている間、価格が動くたびに損益は変わりますが、決済するまでは確定していません。この確定前の損益が含み損益です。決済した時点で確定した損益は実現損益と呼ばれ、口座の残高に反映されます。",[["先物取引","futures-contract"],"の含み損益は、通常",["マーク価格","mark-price"],"で計算されます。",["ロング","long-and-short"],"なら（マーク価格−建値）×数量、ショートなら（建値−マーク価格）×数量です。実際に決済するときは板の価格で約定するため、表示されていた含み損益と、手数料や",["スリッページ","slippage"],"を引いた実現損益には差が出ます。"],[["クロスマージン","cross-margin"],"では、含み益が他のポジションの証拠金として使われることがあり、含み損は口座の証拠金を減らして清算に近づけます。取引所によっては含み益を新しいポジションの証拠金に使えるかどうかの扱いが異なります。また、ROE（証拠金に対する損益率）も表示されますが、",["レバレッジ","leverage"],"によって大きく見える点に注意してください。"]],"example":"BTCが60,000 USDTのときに、0.5 BTCのロングを10倍（証拠金3,000 USDT）で建てたとします。マーク価格が63,000 USDTになると、含み損益は（63,000−60,000）×0.5＝＋1,500 USDTで、証拠金に対するROEは50%です。この時点で決済すると、往復の手数料が合計約20 USDTかかれば、実現損益は約1,480 USDTになります。決済しなければ、価格が戻って含み益が消えることもあります。","mistakes":["含み益を確定した利益のように考え、決済前にその分を使える資金として計算する。","高いレバレッジで大きく見えるROEを、資産全体に対する利回りと混同する。","含み損を「決済しなければ損ではない」と考え、清算価格に近づいていることに気づかない。"],"faq":[{"q":"含み損益と実現損益の違いは何ですか？","a":"含み損益は決済前の評価上の損益、実現損益は決済して確定した損益です。実現損益には手数料などが反映されます。"},{"q":"含み損益はどの価格で計算されますか？","a":"先物取引では多くの場合マーク価格で計算されます。取引所によっては最終取引価格での表示に切り替えられます。"}],"title":"含み損益（未実現損益）とは？計算方法と注意点","description":"含み損益（未実現損益）の意味と計算方法、実現損益との違い、マーク価格やROEの見方とクロスマージンでの注意点を解説します。","related":[["mark-price","マーク価格","マーク価格とは、先物の含み損益や強制ロスカットの判定に使われる「公正な評価価格」のことで、複数の現物取引所の価格をもとに計算され、一時的な価格操作の影響を受けにくくしています。"],["cross-margin","クロスマージン","クロスマージンとは、口座内の利用可能な証拠金をすべてのポジションで共有する方式で、清算を遠ざけやすい一方、損失が口座全体に及ぶ可能性があります。"],["liquidation-price","清算価格（ロスカット価格）","清算価格（ロスカット価格）とは、マーク価格がその水準に達するとポジションが強制ロスカットされる価格のことで、レバレッジと維持証拠金率によって決まります。"],["take-profit","利益確定注文（テイクプロフィット）","利益確定注文（テイクプロフィット）とは、価格が目標の水準に達したときに自動で決済し、含み益を実際の利益として確定させる注文です。"]],"lesson":{"id":"E20","slug":"maintenance-margin","ep":20,"title":"証拠金がゼロになる前に強制終了されるのはなぜか"},"coin":null,"tool":null,"cta":false},"cold-wallet":{"slug":"cold-wallet","cat":"wallets-security","en":"Cold wallet (cold storage)","contentLocale":"ja","term":"コールドウォレット（コールドストレージ）","aka":["コールドストレージ","cold wallet","オフラインウォレット"],"short":"コールドウォレットとは、秘密鍵をインターネットから切り離した環境で保管する暗号資産の保管方法で、遠隔からのハッキングを受けにくいのが特徴です。","body":[["代表例は",["ハードウェアウォレット","hardware-wallet"],"や、オフラインで作成したペーパー",["ウォレット","crypto-wallet"],"です。",["秘密鍵","private-key"],"がネットに出ないため、マルウェアや",["フィッシング","phishing"],"で鍵そのものを抜き取られるリスクを大きく下げられます。"],["取引所も顧客資産の大部分をコールドウォレットで保管し、出金に必要な分だけを",["ホットウォレット","hot-wallet"],"に移す運用をしています。日本の",["暗号資産交換業者","vasp"],"にも、顧客資産をコールドウォレット等で管理する規制上の要件があります。"],"弱点は手間と物理的なリスクです。送金のたびに機器を接続して承認する必要があり、紛失、火災、シードフレーズの盗み見といった現実世界の対策が必要になります。"],"example":"1 BTCを5年保有する予定の人が、ハードウェアウォレットで受取アドレスを作り、取引所から出金したとします。出金手数料が0.0002 BTCなら、着金は0.9998 BTCです。シードフレーズは金属プレートに刻み、自宅と別の場所の2か所に保管します。普段は機器を引き出しにしまい、売却するときだけ接続して署名します。","mistakes":["シードフレーズを写真に撮ってしまい、オフライン保管の意味をなくすこと。","シードフレーズを1か所だけに保管し、火災や紛失に備えないこと。","中古品や非公式ショップで買った機器をそのまま使うこと。"],"faq":[{"q":"コールドウォレットなら絶対に安全ですか？","a":"遠隔攻撃には強いですが、シードフレーズの盗難や紛失、偽サイトでの誤った署名は防げません。保管と署名の手順を守ることが前提です。"},{"q":"少額でもコールドウォレットは必要ですか？","a":"頻繁に使う少額ならホットウォレットで十分という考え方が一般的です。失うと困る金額を長期保有するときに検討する価値があります。"}],"title":"コールドウォレットとは？意味と保管のコツ","description":"コールドウォレット（コールドストレージ）の意味、ホットウォレットとの違い、シードフレーズの保管方法など実践的なポイントを解説します。","related":[["hot-wallet","ホットウォレット","ホットウォレットとは、インターネットに接続された状態で秘密鍵を扱う暗号資産ウォレットのことで、すぐに送金できる反面、オンライン攻撃の対象になりやすいものです。"],["hardware-wallet","ハードウェアウォレット","ハードウェアウォレットとは、秘密鍵を専用の小型デバイス内に保管し、送金の署名を端末の中だけで行う物理的な暗号資産ウォレットです。"],["seed-phrase","シードフレーズ（リカバリーフレーズ）","シードフレーズとは、ウォレットの秘密鍵をすべて復元できる12語または24語の英単語の並びで、ウォレットのマスターキーにあたるものです。"],["multisig-wallet","マルチシグウォレット","マルチシグウォレットとは、送金に複数の秘密鍵の署名を必要とするウォレットで、たとえば3つの鍵のうち2つの署名がそろわないと資産を動かせない仕組みです。"]],"lesson":{"id":"E03","slug":"exchange-vs-wallet","ep":3,"title":"私のコインはどこ？取引所とウォレットの違い"},"coin":null,"tool":null,"cta":false},"rug-pull":{"slug":"rug-pull","cat":"wallets-security","en":"Rug pull","contentLocale":"ja","term":"ラグプル","aka":["rug pull","ラグ","持ち逃げ詐欺"],"short":"ラグプルとは、暗号資産プロジェクトの開発者が流動性や集めた資金を突然引き揚げ、トークンの価格をほぼゼロにして投資家に損失を負わせる詐欺的な行為です。","body":[["英語の「敷物を引き抜く」が語源です。典型的なのは、開発者が新しいトークンを作ってDEXに",["流動性","liquidity"],"を提供し、話題を集めて買いが入ったところで流動性を全部引き出すパターンです。売る相手がいなくなり、保有者はトークンを売れなくなります。"],"ほかにも、開発者が大量のトークンを隠し持って一気に売る、コントラクトに買えるが売れない仕掛けを入れる、資金を集めた後にサイトやSNSを消す、といった手口があります。",["見極めのポイントは、流動性がロックされているか、開発者や上位",["アドレス","wallet-address"],"の保有比率、コントラクトに不審な権限がないか、運営者の身元や過去の実績です。",["ミームコイン","memecoin"],"など新しいトークンほど慎重に確認しましょう。"]],"example":["あるトークンのDEX",["プール","liquidity-pool"],"に、10 ETHと1億トークンの流動性があるとします。話題になって買いが続き、プールが50 ETHと2,000万トークンになった時点で、開発者が流動性をすべて引き出しました。プールが空になり、残りの8,000万トークンを持つ人たちは、それを売ってETHに換える相手がいません。画面上の評価額があっても、現金化できない状態です。"],"mistakes":["SNSで話題になっているという理由だけで、出たばかりのトークンを買うこと。","流動性のロック状況や上位保有アドレスの比率を確認しないこと。","少額の売却テストをせずに大きく買い、売れないトークンだと後から気付くこと。"],"faq":[{"q":"ラグプルされたトークンは取り戻せますか？","a":"ほとんどの場合、取り戻すのは困難です。ブロックチェーン上の送金は取り消せず、運営者が匿名であれば追跡や法的手段も難しくなります。"},{"q":"流動性がロックされていれば安全ですか？","a":"流動性の引き揚げは防げますが、開発者の大量売却やコントラクトの不審な権限など、他の手口までは防げません。複数の項目をあわせて確認しましょう。"}],"title":"ラグプルとは？意味と典型的な手口・見抜き方","description":"暗号資産のラグプルの意味、流動性の引き揚げなど典型的な手口、新しいトークンを買う前に確認すべきポイントを解説します。","related":[["memecoin","ミームコイン","ミームコインとは、ネット上のジョークや動物、キャラクター、流行などを題材にした暗号資産で、実用性よりもコミュニティの話題性で価格が動きやすい銘柄のことです。"],["liquidity-pool","流動性プール（リクイディティプール）","流動性プールとは、DEXで取引相手として機能するように、利用者が2種類以上のトークンを預け入れてつくる資金の集まりで、預けた人は取引手数料の一部を受け取ります。"],["token-approval","トークン承認（Approve・アローワンス）","トークン承認とは、DEXなどのスマートコントラクトに、あなたのウォレットから特定のトークンを指定量まで引き出す権限を与える操作です。"],["dex","DEX（分散型取引所）","DEX（分散型取引所）とは、運営会社が資産を預からず、スマートコントラクトを使ってウォレット同士で直接暗号資産を交換できる取引所です。"]],"lesson":{"id":"E11","slug":"scam-red-flags","ep":11,"title":"「儲けさせてあげる」と言う人がいたら、まず何を要求しているか見極めよう"},"coin":null,"tool":"/topics/meme-coins","cta":false},"oracle":{"slug":"oracle","cat":"defi","en":"Blockchain oracle","contentLocale":"ja","term":"オラクル（ブロックチェーンオラクル）","aka":["ブロックチェーンオラクル","oracle","価格オラクル"],"short":"オラクルとは、価格や天気、試合結果など、ブロックチェーンの外にあるデータをスマートコントラクトに届ける仕組みのことです。","body":[[["スマートコントラクト","smart-contract"],"は、",["ブロックチェーン","blockchain"],"の外の情報を自分で取りに行くことができません。たとえばレンディングでは担保の時価、",["無期限先物","perpetual-futures"],"のDEXでは清算の基準価格が必要で、それをオラクルが提供します。Chainlinkは代表的なオラクルネットワークです。"],"信頼性の高いオラクルは、複数の取引所やデータ提供者の価格を集めて中央値などを取り、1か所の異常な価格に左右されにくくしています。更新の頻度や、価格がどれだけ動いたら更新するかも設計の重要なポイントです。",["オラクルが誤った価格を伝えると、正常なポジションが清算されたり、攻撃者が不当に資金を引き出したりできてしまいます。過去のDeFiハッキングには、",["流動性","liquidity"],"の薄い単一DEXの価格をオラクルとして使っていたことが原因のものもあります。"]],"example":["あるレンディングが、ETH価格を流動性の薄い1つのDEXだけから取得しているとします。攻撃者が",["フラッシュローン","flash-loan"],"でそのDEXのETHを大量に買い、価格を一時的に3,000ドルから6,000ドルに吊り上げます。プロトコルは担保の10 ETHを6万ドルと評価し、本来の3万ドルを大きく超える額を貸してしまいます。複数の市場の価格を集計するオラクルなら、1つのDEXの異常値はほぼ無視されます。"],"mistakes":["オラクルの価格は取引所の画面と常に一致すると思い込むこと。","DeFiを選ぶときに、どのオラクルを使っているかを確認しないこと。","急変動時にオラクルの更新遅れで清算価格がずれる可能性を考えないこと。"],"faq":[{"q":"なぜスマートコントラクトは外部データを直接取得できないのですか？","a":"ブロックチェーンでは、全ノードが同じ計算をして同じ結果になる必要があります。外部サイトの値は取得のたびに変わる可能性があるため、オラクルがデータを取引としてチェーン上に書き込む方式をとります。"},{"q":"オラクル問題とは何ですか？","a":"ブロックチェーン自体が安全でも、外部データの正しさはオラクルに依存するという課題のことです。データ源の分散や複数ノードでの検証などで対策されています。"}],"title":"オラクルとは？ブロックチェーンと外部データの橋渡し","description":"ブロックチェーンのオラクルの意味、DeFiで価格データが必要な理由、オラクルの操作による攻撃の仕組みと対策を解説します。","related":[["smart-contract","スマートコントラクト","スマートコントラクトとは、ブロックチェーン上に置かれ、あらかじめ決められた条件が満たされると自動的に実行されるプログラムのことです。"],["defi-lending","DeFiレンディング","DeFiレンディングとは、スマートコントラクト上で暗号資産を貸し出して利息を得たり、担保を預けて別の暗号資産を借りたりできる仕組みです。"],["index-price","インデックス価格","インデックス価格とは、複数の主要な現物取引所の価格を加重平均して算出した、その暗号資産の現物の基準価格のことで、マーク価格や資金調達率の計算に使われます。"],["flash-loan","フラッシュローン","フラッシュローンとは、担保なしで暗号資産を借りられる代わりに、同じトランザクション内で必ず返済しなければならないDeFi特有の借入です。"]],"lesson":null,"coin":{"slug":"chainlink","name":"Chainlink","symbol":"LINK"},"tool":null,"cta":false},"launchpad":{"slug":"launchpad","cat":"exchange-features","en":"Launchpad (token sale)","contentLocale":"ja","term":"ローンチパッド（Launchpad）","aka":["Launchpad","IEO","トークンセール"],"short":"ローンチパッドとは、取引所などのプラットフォームを通じて、上場前の新しいトークンを決められた価格で購入できるトークンセールの仕組みのことです。","body":[["取引所が運営するローンチパッドは、IEO（Initial Exchange Offering）とも呼ばれます。取引所がプロジェクトを審査したうえで販売を行い、販売後にその取引所へ",["上場","token-listing"],"するのが一般的です。日本の国内取引所でもIEOが実施されることがあります。"],"参加方法は、一定期間の保有額に応じて申込枠が決まる方式、抽選方式、先着方式などがあります。申込額が販売枠を大きく上回ると、実際に買える量は按分され、残りの資金は返還されます。","販売価格が上場後の価格を下回る保証はありません。上場後に販売価格を割り込むこともありますし、ロック期間（すぐに売れない期間）やベスティング（段階的な受け取り）が設定されている場合もあります。販売条件と、総供給量のうち市場に出回る割合を確認しておきましょう。"],"example":["あるローンチパッドで、新トークンを1枚0.10 USDTで2,000,000枚、合計200,000 USDT分販売するとします。申込総額が4,000,000 USDTに達した場合、倍率は20倍で、あなたが1,000 USDT申し込むと実際に購入できるのは50 USDT分、つまり500枚です。残りの950 USDTは返還されます。上場後に価格が0.30 USDTになれば500枚は150 ",["USDT","usdt"],"、0.08 USDTまで下がれば40 USDTになります。申込額の大きさと実際の購入額が大きく違う点に注意が必要です。"],"mistakes":["申し込んだ金額の全額分を購入できると考え、按分で少ししか買えないことを想定しない。","取引所のローンチパッドを名乗る偽のトークンセールに送金してしまう。","ロック期間やベスティングの条件を確認せず、すぐに売れると思い込む。"],"faq":[{"q":"ローンチパッドで買えば必ず利益が出ますか？","a":"いいえ、上場後に販売価格を下回ることもあります。プロジェクトの内容、販売条件、市場に出回る供給量を確認して判断する必要があります。"},{"q":"IEOとICOの違いは何ですか？","a":"ICOはプロジェクトが自ら直接トークンを販売する方法で、IEOは取引所が審査と販売を担う方法です。IEOは取引所の審査がある分、一定の確認が入ります。"}],"title":"ローンチパッドとは？IEOの仕組みと注意点","description":"ローンチパッド（IEO）の意味、トークンセールの参加方式と按分の仕組み、ロック期間や上場後の値下がりなどの注意点を解説します。","related":[["launchpool","ローンチプール（Launchpool）","ローンチプールとは、取引所が指定した暗号資産やステーブルコインを一定期間預け入れると、新しく上場するトークンを報酬として受け取れる取引所のキャンペーン型サービスです。"],["token-listing","上場（トークン上場）","トークン上場とは、取引所が新しい暗号資産の取扱いを開始し、利用者がその取引所で入金・売買・出金できるようにすることです。"],["token-unlock","トークンアンロック","トークンアンロックとは、チームや投資家などに配分されロックされていたトークンが、決められたスケジュールに従って売却や移転できるようになることです。"],["airdrop","エアドロップ","エアドロップとは、プロジェクトが特定の条件を満たしたウォレットやユーザーに、トークンを無料で配布することです。"]],"lesson":null,"coin":null,"tool":"/activities","cta":false},"sub-account":{"slug":"sub-account","cat":"exchange-features","en":"Sub-account","contentLocale":"ja","term":"サブアカウント","aka":["サブ口座","子アカウント","sub-account"],"short":"サブアカウントとは、1つのメインアカウントの下に作成できる独立した口座で、資金や取引、APIキーを用途ごとに分けて管理するための取引所の機能です。","body":[["多くの海外取引所では、メインアカウントのKYCを済ませておけば、追加の",["本人確認","kyc"],"なしで複数のサブアカウントを作れます。メインとサブの間、またはサブ同士の資金移動は、通常は無料で即時に行えます。"],["代表的な使い方は、戦略ごとの資金の分離です。たとえば、長期保有の現物、先物の短期取引、取引ボット用、",["コピートレード","copy-trading"],"用と口座を分けておけば、1つの戦略で大きな損失が出ても、他の口座の資産には影響しません。損益の記録もわかりやすくなります。"],"APIキーをサブアカウント単位で発行し、出金権限を付けずに取引だけを許可しておくと、外部ツールを使う際のリスクを抑えられます。サブアカウントで使える機能や作成できる数は取引所によって異なるので、事前に確認しておきましょう。"],"example":["あなたが10,000 USDTを持っていて、7,000 USDTを現物の長期保有に、2,000 USDTを",["先物取引","futures-contract"],"に、1,000 USDTを",["グリッドボット","grid-trading-bot"],"に使いたいとします。それぞれをメイン口座、サブアカウントA、サブアカウントBに分けておけば、先物取引で清算が起きても失うのはサブアカウントAの2,000 USDTまでです。もしすべてを1つの",["クロスマージン","cross-margin"],"口座で運用していたら、先物の損失を補うために残りの8,000 USDTまで証拠金として使われる可能性がありました。"],"mistakes":["サブアカウントを作れば別の本人として扱われると考え、1人1回のキャンペーンに複数参加しようとする。","外部ツール用のAPIキーに出金権限を付けたまま発行してしまう。","どのサブアカウントにいくら入れたかを把握せず、資産の管理がかえって複雑になる。"],"faq":[{"q":"サブアカウントごとにKYCが必要ですか？","a":"多くの取引所では、メインアカウントのKYCが完了していればサブアカウントに追加の本人確認は不要です。ただし規約は取引所ごとに異なります。"},{"q":"サブアカウントの間で資金を移すと手数料はかかりますか？","a":"同じメインアカウント内での振替は、一般的には無料で即時に反映されます。ブロックチェーンを経由しないため、ガス代もかかりません。"}],"title":"サブアカウントとは？取引所での使い方とメリット","description":"取引所のサブアカウントの意味と使い方、戦略ごとに資金を分けるメリット、APIキーの権限設定などの注意点を具体例で解説します。","related":[["unified-trading-account","統合取引口座（UTA）","統合取引口座（UTA）とは、現物、先物、オプションなどの取引を1つの口座でまとめて行い、口座内の資産全体を証拠金として共有できる取引所の口座形態です。"],["isolated-margin","分離マージン（アイソレーテッドマージン）","分離マージンとは、ポジションごとに証拠金を割り当てて管理する方式で、そのポジションが清算されても失うのは割り当てた証拠金だけに限られます。"],["two-factor-authentication","二段階認証（2FA）","二段階認証（2FA）とは、パスワードに加えて認証アプリのコードやセキュリティキーなど別の要素を求めることで、不正ログインを防ぐ仕組みです。"],["copy-trading","コピートレード","コピートレードとは、取引所上で選んだ他のトレーダーの売買を、自分の口座で自動的に同じように再現する仕組みのことです。"]],"lesson":null,"coin":null,"tool":null,"cta":false},"vip-tier":{"slug":"vip-tier","cat":"exchange-features","en":"VIP fee tier","contentLocale":"ja","term":"VIPランク（手数料ティア）","aka":["VIPレベル","手数料ティア","VIP fee tier"],"short":"VIPランクとは、取引所が利用者の取引量や資産残高に応じて設定する段階的な会員区分で、ランクが上がるほど取引手数料が安くなる仕組みです。","body":[["多くの取引所では、過去30日間の",["取引量","trading-volume"],"と、口座の資産残高（または取引所トークンの保有量）を基準にVIPランクが決まります。一般的には、どちらかの条件を満たせばランクが上がり、",["メイカー手数料","maker-taker-fees"],"とテイカー手数料がそれぞれ引き下げられます。"],["現物と先物で別々のランク表が用意されていることが多く、上位ランクでは手数料のほか、出金上限の引き上げや専任の",["サポート","support-and-resistance"],"などの特典がつく場合もあります。",["マーケットメイカー","market-maker"],"向けには、メイカー手数料がゼロやマイナス（リベート）になるプログラムもあります。"],["一般の利用者がVIPランクを目指して取引量を増やすと、手数料の節約以上に取引によるリスクが増えることがあります。現在のランクと次のランクの条件、そして",["紹介コード","referral-code"],"による還元と組み合わせられるかを確認しておくのが現実的です。"]],"example":"ある取引所で、通常ランクの先物のテイカー手数料が0.05%、30日間の取引量が5,000,000 USDT以上で上がるVIP1が0.04%だとします。あなたの取引量が月4,000,000 USDTなら手数料は2,000 USDTです。仮にVIP1の条件を満たしていれば、同じ取引量でも1,600 USDTで、差は400 USDTです。ただし、VIP1に届かせるために不要な取引を1,000,000 USDT分増やすと、その手数料だけで約500 USDTかかり、節約分を上回ってしまいます。手数料率は説明用の例です。","mistakes":["ランクを上げるためだけに不要な取引を増やし、節約分以上の手数料と損失を出す。","現物と先物のランク表が別であることを知らず、片方の取引量で両方が下がると考える。","ランクの判定期間が過去30日間などで、取引量が減るとランクが下がることを見落とす。"],"faq":[{"q":"VIPランクはどのくらいの頻度で更新されますか？","a":"多くの取引所では毎日、過去30日間の取引量や資産残高をもとに再計算されます。条件を満たさなくなるとランクは下がります。"},{"q":"VIPランクと紹介コードの還元は併用できますか？","a":"取引所やプログラムによって異なります。併用できる場合もあれば、一定のランク以上では還元の対象外になる場合もあるので、条件を確認してください。"}],"title":"VIPランクとは？取引所の手数料ティアの仕組み","description":"取引所のVIPランク（手数料ティア）の意味、取引量と資産残高による判定の仕組み、ランクを目指すときの注意点を計算例で解説します。","related":[["maker-taker-fees","メイカー手数料・テイカー手数料（Maker/Taker）","メイカー手数料・テイカー手数料とは、板に注文を置いて流動性を提供した側（メイカー）と、板の注文を即座に約定させた側（テイカー）で分けて設定される取引手数料のことです。"],["referral-code","紹介コード（手数料キャッシュバック）","紹介コードとは、取引所の口座開設時に入力することで、紹介者と新規利用者の双方に手数料の割引やキャッシュバックなどの特典が付与される仕組みです。"],["trading-volume","取引量（出来高）","取引量（出来高）とは、一定期間に実際に売買が成立した暗号資産の数量や金額の合計のことで、一般には24時間の値が使われます。"],["market-maker","マーケットメイカー（MM）","マーケットメイカーとは、買い注文と売り注文の両方を板に出し続けて、他の参加者がいつでも売買できる状態を作る事業者やトレーダーのことです。"]],"lesson":null,"coin":null,"tool":"/rates","cta":false},"token-listing":{"slug":"token-listing","cat":"exchange-features","en":"Token listing","contentLocale":"ja","term":"上場（トークン上場）","aka":["新規上場","取扱開始","リスティング","token listing"],"short":"トークン上場とは、取引所が新しい暗号資産の取扱いを開始し、利用者がその取引所で入金・売買・出金できるようにすることです。","body":[["取引所は、プロジェクトの技術、チームの情報、",["流動性","liquidity"],"、法令への適合などを審査したうえで上場を決めます。日本の国内取引所では、新しい銘柄を取り扱う際に業界団体の審査なども関係するため、海外取引所より上場までに時間がかかる傾向があります。"],"上場の告知が出ると、多くの場合「入金開始」「取引開始」「出金開始」の日時が順番に発表されます。最初は現物だけで、後から先物や運用サービスに追加されることもあります。大手取引所への上場は注目を集め、取引開始直後は価格が大きく上下しやすいです。",["注意したいのは、上場直後の値動きの激しさと、偽の上場情報です。取引開始直後は板が薄く、",["成行注文","market-order"],"で大きな",["スリッページ","slippage"],"が出ることがあります。また、SNSで出回る上場の噂や、同じ名前の偽トークンに注意し、必ず取引所の公式発表とコントラクト",["アドレス","wallet-address"],"を確認しましょう。"]],"example":["ある新トークンが、取引所で午後6時に取引開始になったとします。開始直後の板では、売り注文が1.00 USDTに5,000枚、1.20 USDTに3,000枚、1.50 USDTに2,000枚しか並んでいませんでした。この状態で10,000 USDT分の成行買いを出すと、5,000枚を5,000 ",["USDT","usdt"],"、3,000枚を3,600 USDT、残り1,400 USDTで約933枚を1.50 USDTで買うことになり、平均約1.12 USDTで約8,933枚を取得します。最初の価格より約12%高く買った計算です。上場直後は",["指値注文","limit-order"],"で価格を指定するほうが安全です。"],"mistakes":["上場直後に成行で大きく買い、板の薄さによるスリッページで高値をつかむ。","SNSで流れた上場の噂だけを信じて、公式発表を確認せずに先回りして買う。","同じ名前の偽トークンを、コントラクトアドレスを確認せずにDEXで買ってしまう。"],"faq":[{"q":"大手取引所に上場すると価格は上がりますか？","a":"注目が集まって一時的に大きく動くことはありますが、上がるとは限りません。上場後に売りが増えて下がるケースも多くあります。"},{"q":"上場の情報はどこで確認すればよいですか？","a":"取引所の公式サイトのお知らせや、公式アプリの告知で確認してください。SNSのスクリーンショットだけで判断するのは避けましょう。"}],"title":"トークン上場とは？取引所の新規上場の流れと注意点","description":"トークン上場の意味、取引所の審査と入金・取引・出金開始の流れ、上場直後のスリッページや偽情報への注意点を解説します。","related":[["delisting","上場廃止（デリスティング）","上場廃止とは、取引所がある暗号資産の取扱いを終了し、その取引所での売買、さらに一定期間後には入金や出金もできなくなることです。"],["launchpool","ローンチプール（Launchpool）","ローンチプールとは、取引所が指定した暗号資産やステーブルコインを一定期間預け入れると、新しく上場するトークンを報酬として受け取れる取引所のキャンペーン型サービスです。"],["liquidity","流動性（リクイディティ）","流動性とは、ある暗号資産を価格を大きく動かさずに、すぐ売買できる度合いのことで、板の厚みやスプレッドの狭さで判断します。"],["altcoin","アルトコイン","アルトコインとは、ビットコイン以外の暗号資産の総称で、イーサリアムやソラナのような大型銘柄から、新しく小規模な銘柄までを含みます。"]],"lesson":null,"coin":null,"tool":"/activities","cta":false},"stock-perpetuals":{"slug":"stock-perpetuals","cat":"tokenized-assets","en":"Stock perpetuals","contentLocale":"ja","term":"株式の無期限先物（株式パーペチュアル）","aka":["株式パーペチュアル","株価連動パーペチュアル","stock perpetuals"],"short":"株式の無期限先物とは、個別株や株価指数の価格に連動し、満期のない先物契約として証拠金とレバレッジで取引できるデリバティブ商品のことです。","body":[[["暗号資産","cryptocurrency"],"の",["無期限先物（パーペチュアル）","perpetual-futures"],"と同じ仕組みを、株価に応用したものです。トレーダーはUSDTなどを証拠金にして、",["ロング","long-and-short"],"やショートのポジションを持ちます。株式そのものは保有せず、価格差だけを決済します。Hyperliquidなどのオンチェーン取引所や、一部の",["中央集権型取引所","centralized-exchange"],"が提供しています。"],["価格を株価に近づけるために、",["資金調達率（ファンディングレート）","funding-rate"],"が使われます。株式市場が閉まっている間は、元となる株価が更新されないため、取引所ごとに参照価格の扱いや取引の制限などのルールが異なります。"],[["レバレッジ","leverage"],"をかけられる分、株価が少し動いただけで強制ロスカット（清算）が起こり得ます。株式の決算発表や市場の開始時刻には価格が大きく飛ぶこともあるため、休場明けのギャップのリスクを理解しておく必要があります。"]],"example":"ある株式の無期限先物が200 USDTで取引されていて、あなたが500 USDTを証拠金に、5倍のレバレッジで2,500 USDT分のロングを持ったとします。株価が4%上がって208 USDTになれば、利益は2,500×0.04で100 USDT、証拠金に対して20%です。逆に、決算発表で週明けに株価が16%下がって168 USDTで始まると、損失は400 USDTで、維持証拠金を考えると清算ライン付近に達します。さらに資金調達率が8時間ごとに0.01%なら、2,500 USDTのポジションで1日約0.75 USDTを支払う計算です。","mistakes":["株式なので暗号資産よりも安全だと考え、高いレバレッジをかけてしまう。","休場中や決算発表前後に価格が大きく飛ぶリスクを考えずにポジションを持ち越す。","株式そのものを持っていると勘違いし、配当や議決権があると思い込む。"],"faq":[{"q":"株式の無期限先物は株式市場が閉まっている間も取引できますか？","a":"取引所によって異なります。休場中も取引できる場合でも、参照価格の扱いが変わったり、値動きが制限されたりすることがあるので、取引所の仕様を確認してください。"},{"q":"株式の無期限先物で配当はもらえますか？","a":"株式そのものを保有していないため、配当は受け取れません。取引所によっては配当落ちの影響を価格や資金調達で調整することがあります。"}],"title":"株式の無期限先物とは？株式パーペチュアルの仕組み","description":"株式の無期限先物（株式パーペチュアル）の意味と仕組み、資金調達率と休場中の扱い、レバレッジと清算のリスクを計算例で解説します。","related":[["tokenized-stocks","トークン化株式","トークン化株式とは、実際の株式や株式に連動する権利をブロックチェーン上のトークンとして発行し、暗号資産と同じように保有や送金ができるようにしたものです。"],["perpetual-futures","無期限先物（パーペチュアル）","無期限先物（パーペチュアル）とは、満期日がなく、いつまでもポジションを持ち続けられる先物契約で、資金調達率（ファンディングレート）の支払いによって価格を現物価格に近づける仕組みです。"],["funding-rate","資金調達率（ファンディングレート）","資金調達率（ファンディングレート）とは、無期限先物の価格を現物価格に近づけるため、ロングとショートの間で定期的にやり取りされる支払いの率のことです。"],["leverage","レバレッジ","レバレッジとは、差し入れた証拠金の何倍もの金額のポジションを持てる仕組みのことで、利益と損失の両方が倍率に応じて大きくなります。"]],"lesson":null,"coin":null,"tool":"/topics/tokenized-stocks-vs-perpetuals","cta":true}});
